package com.andye.warmod.radar;import com.andye.warmod.WarMod;import com.andye.warmod.antiair.*;import com.andye.warmod.entity.IncomingWarheadEntity;import com.andye.warmod.icbm.*;import com.andye.warmod.radar.network.*;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.server.level.*;import net.minecraft.world.phys.Vec3;
public final class RadarTrackingService{public static final int MAX_STRATEGIC_TRACKS_PER_LEVEL=128,MAX_INTERCEPTOR_TRACKS_PER_LEVEL=2048,MAX_RECENT_IMPACTS_PER_LEVEL=128;public static final long RECENT_IMPACT_RETENTION_TICKS=1200,IMPACT_TRACK_RETENTION_TICKS=200;private static final UUID SERVER_OWNER=new UUID(0,0);private static final Map<ServerLevel,State> STATES=new WeakHashMap<>();private RadarTrackingService(){}
public static synchronized void registerIcbm(ServerLevel l,IcbmFlightPlan p){State s=state(l);if(s.tracks.containsKey(p.missileId()))return;makeStrategicRoom(l,s);ServerPlayer o=l.getServer().getPlayerList().getPlayer(p.ownerPlayerId());RadarTrack t=new RadarTrack(p.missileId(),RadarTrackKind.ICBM,p.ownerPlayerId(),bounded(o==null?"SERVER":o.getGameProfile().name()),p.payloadType(),null,p.launchGameTime(),p,null,RadarTrackPhase.IGNITION);s.tracks.put(t.trackId,t);upsert(l,t);}
public static synchronized void updateIcbmPlan(ServerLevel l,IcbmFlightPlan p){RadarTrack t=track(l,p.missileId());if(t!=null&&t.kind==RadarTrackKind.ICBM){t.carrierFlightPlan=p;upsert(l,t);}}
public static synchronized void registerDirectWarhead(ServerLevel l,ServerPlayer owner,WarheadLaunchService.LaunchResult launch){State s=state(l);if(s.tracks.containsKey(launch.radarRootTrackId()))return;makeStrategicRoom(l,s);UUID ownerId=owner==null?SERVER_OWNER:owner.getUUID();RadarTrack t=new RadarTrack(launch.radarRootTrackId(),RadarTrackKind.DIRECT_WARHEAD,ownerId,bounded(owner==null?"SERVER":owner.getGameProfile().name()),launch.payloadType(),null,launch.launchGameTime(),null,null,RadarTrackPhase.PAYLOAD_DELIVERY);attach(s,t,launch);s.tracks.put(t.trackId,t);upsert(l,t);}
public static synchronized void registerTerminalSeparation(ServerLevel l,UUID root,WarheadLaunchService.LaunchResult launch){RadarTrack t=track(l,root);if(t==null)return;attach(state(l),t,launch);t.phase=RadarTrackPhase.PAYLOAD_DELIVERY;t.lastStateChangeGameTime=l.getGameTime();upsert(l,t);}
public static synchronized void reconcileWarhead(ServerLevel l,IncomingWarheadEntity e){if(e.warheadId()==null||track(l,e.radarRootTrackId())!=null)return;registerDirectWarhead(l,e.ownerPlayerId()==null?null:l.getServer().getPlayerList().getPlayer(e.ownerPlayerId()),new WarheadLaunchService.LaunchResult(e.warheadId(),e.startPosition(),e.intendedTarget(),e.launchGameTime(),e.flightTicks(),e.visualSeed(),e.payloadType(),e.radarRootTrackId()));}
public static synchronized void registerInterceptor(ServerLevel l,UUID id,UUID owner,String name,RadarInterceptorPlanSnapshot plan){State s=state(l);if(s.tracks.containsKey(id)||interceptorCount(s)>=MAX_INTERCEPTOR_TRACKS_PER_LEVEL)return;RadarTrack t=new RadarTrack(id,RadarTrackKind.INTERCEPTOR,owner==null?SERVER_OWNER:owner,bounded(name),null,plan.variant(),plan.launchGameTime(),null,plan,RadarTrackPhase.IGNITION);s.tracks.put(id,t);upsert(l,t);}
public static synchronized void updateInterceptorRoute(ServerLevel l,UUID id,RadarInterceptorRouteSnapshot route){RadarTrack t=track(l,id);if(t==null||t.interceptorPlan==null)return;var p=t.interceptorPlan;t.interceptorPlan=new RadarInterceptorPlanSnapshot(p.variant(),p.targetRootTrackId(),p.launchPosition(),p.burnoutPosition(),p.noTargetHorizontalOffset(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.guidanceTier(),p.maximumMissDistance(),Optional.of(route),p.fallback());t.phase=RadarTrackPhase.INTERCEPT;upsert(l,t);}
public static synchronized void updateInterceptorFallback(ServerLevel l,UUID id,RadarInterceptorFallbackSnapshot fallback){RadarTrack t=track(l,id);if(t==null||t.interceptorPlan==null)return;var p=t.interceptorPlan;t.interceptorPlan=new RadarInterceptorPlanSnapshot(p.variant(),p.targetRootTrackId(),p.launchPosition(),p.burnoutPosition(),p.noTargetHorizontalOffset(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.guidanceTier(),p.maximumMissDistance(),p.route(),Optional.of(fallback));upsert(l,t);}
public static synchronized void updateInterceptorPhase(ServerLevel l,UUID id,RadarTrackPhase phase){RadarTrack t=track(l,id);if(t!=null&&t.kind==RadarTrackKind.INTERCEPTOR&&t.phase!=phase){t.phase=phase;t.lastStateChangeGameTime=l.getGameTime();upsert(l,t);}}
public static void removeInterceptor(ServerLevel l,UUID id,RadarRemovalReason r){removeTrack(l,id,r);}public static void registerInterception(ServerLevel l,RadarInterceptionSnapshot i){RadarSubscriptionManager.broadcast(l,new ClientboundRadarInterceptionPayload(i.interceptorId(),i.targetRootTrackId(),i.position(),i.gameTime(),i.variant(),i.interceptedPayload()));}public static synchronized void registerImpact(ServerLevel l,UUID warhead,UUID root,Vec3 pos,WarheadPayloadType payload,float scale){State s=state(l);RadarTrack t=s.tracks.get(root);long now=l.getGameTime();RadarImpactSnapshot i=new RadarImpactSnapshot(root,warhead,pos,now,payload,scale);if(t!=null){t.terminalPlans.remove(warhead);s.terminalToRoot.remove(warhead);if(t.terminalPlans.isEmpty()){t.phase=RadarTrackPhase.IMPACT;t.impactPosition=pos;t.impactGameTime=now;t.impactVisualScale=scale;}else{var primary=t.terminalPlans.values().iterator().next();t.terminalWarheadId=primary.warheadId();t.terminalStartPosition=primary.startPosition();t.terminalTargetPosition=primary.targetPosition();t.terminalLaunchGameTime=primary.launchGameTime();t.terminalFlightTicks=primary.flightTicks();t.terminalVisualSeed=primary.visualSeed();}upsert(l,t);}s.impacts.addLast(i);while(s.impacts.size()>MAX_RECENT_IMPACTS_PER_LEVEL)s.impacts.removeFirst();RadarSubscriptionManager.broadcast(l,new ClientboundRadarImpactPayload(i));}
public static synchronized void removeTrack(ServerLevel l,UUID id,RadarRemovalReason reason){State s=STATES.get(l);if(s==null)return;RadarTrack t=s.tracks.remove(id);if(t==null)return;for(UUID child:t.terminalPlans.keySet())s.terminalToRoot.remove(child);RadarSubscriptionManager.broadcast(l,new ClientboundRadarTrackRemovePayload(id,reason));}
public static synchronized List<RadarTrackSnapshot> snapshotTracks(ServerLevel l){State s=STATES.get(l);return s==null?List.of():s.tracks.values().stream().map(RadarTrack::snapshot).toList();}
public static synchronized List<RadarTrackTelemetry> currentTelemetry(ServerLevel l,long time){State s=STATES.get(l);if(s==null)return List.of();List<RadarTrackTelemetry> out=new ArrayList<>();for(RadarTrack t:s.tracks.values()){if(t.phase==RadarTrackPhase.IMPACT)continue;Vec3 p,v,target;if(t.kind==RadarTrackKind.INTERCEPTOR&&t.interceptorPlan!=null){var ip=t.interceptorPlan;long boostEnd=ip.launchGameTime()+ip.ignitionTicks()+ip.boostTicks();if(time<boostEnd){p=AntiAirTrajectory.boostPosition(ip.launchPosition(),ip.burnoutPosition(),ip.noTargetHorizontalOffset(),ip.ignitionTicks(),ip.boostTicks(),time-ip.launchGameTime());v=AntiAirTrajectory.boostVelocity(ip.launchPosition(),ip.burnoutPosition(),ip.noTargetHorizontalOffset(),ip.ignitionTicks(),ip.boostTicks(),time-ip.launchGameTime());target=ip.route().map(RadarInterceptorRouteSnapshot::resolvedInterceptPosition).orElse(ip.burnoutPosition());}else if(ip.fallback().isPresent()&&time>=ip.fallback().get().transitionGameTime()){var f=ip.fallback().get();p=AntiAirFallbackTrajectory.positionAt(f.transitionPosition(),f.transitionVelocity(),time-f.transitionGameTime());v=AntiAirFallbackTrajectory.velocityAt(f.transitionVelocity(),time-f.transitionGameTime());target=p;}else if(ip.route().isPresent()){var r=ip.route().get();AntiAirRoute route=new AntiAirRoute(ip.burnoutPosition(),r.controlPoint1(),r.controlPoint2(),r.resolvedInterceptPosition(),r.interceptTicks());p=route.position(time-r.routeLockGameTime());v=route.velocity(time-r.routeLockGameTime());target=r.resolvedInterceptPosition();}else{p=ip.burnoutPosition();v=Vec3.ZERO;target=p;}}else if(t.terminalWarheadId!=null){double e=Math.max(0,time-t.terminalLaunchGameTime);p=WarheadTrajectory.position(t.terminalStartPosition,t.terminalTargetPosition,e,t.terminalFlightTicks);v=WarheadTrajectory.velocity(t.terminalStartPosition,t.terminalTargetPosition,e,t.terminalFlightTicks);target=t.terminalTargetPosition;}else if(t.carrierFlightPlan!=null){double e=Math.max(0,time-t.carrierFlightPlan.launchGameTime());p=IcbmTrajectory.position(t.carrierFlightPlan,e);v=IcbmTrajectory.velocity(t.carrierFlightPlan,e);target=t.carrierFlightPlan.intendedTarget();}else continue;out.add(new RadarTrackTelemetry(t.trackId,t.kind,Optional.ofNullable(t.payloadType),Optional.ofNullable(t.interceptorVariant),t.phase,p,v,target,time,t.snapshot()));}return List.copyOf(out);}
public static synchronized List<RadarImpactSnapshot> snapshotImpacts(ServerLevel l){State s=STATES.get(l);return s==null?List.of():List.copyOf(s.impacts);}public static void reconcileIcbmFlights(ServerLevel l){for(var p:IcbmFlightControllerManager.snapshot(l))registerIcbm(l,p);}public static synchronized void tick(ServerLevel l){State s=STATES.get(l);if(s==null)return;long now=l.getGameTime();for(RadarTrack t:new ArrayList<>(s.tracks.values())){if(t.phase==RadarTrackPhase.IMPACT){if(now-t.impactGameTime>IMPACT_TRACK_RETENTION_TICKS)removeTrack(l,t.trackId,RadarRemovalReason.EXPIRED);}else if(t.carrierFlightPlan!=null&&t.terminalWarheadId==null){long e=Math.max(0,now-t.carrierFlightPlan.launchGameTime());RadarTrackPhase p=e<t.carrierFlightPlan.ignitionTicks()?RadarTrackPhase.IGNITION:e<t.carrierFlightPlan.ignitionTicks()+t.carrierFlightPlan.boostTicks()?RadarTrackPhase.BOOST:RadarTrackPhase.MIDCOURSE;if(p!=t.phase){t.phase=p;upsert(l,t);}}}s.impacts.removeIf(i->now-i.impactGameTime()>RECENT_IMPACT_RETENTION_TICKS);}public static synchronized void clear(ServerLevel l){STATES.remove(l);}public static synchronized void clearAll(){STATES.clear();}
private static RadarTrack track(ServerLevel l,UUID id){State s=STATES.get(l);return s==null?null:s.tracks.get(id);}private static State state(ServerLevel l){return STATES.computeIfAbsent(l,k->new State());}private static void attach(State s,RadarTrack t,WarheadLaunchService.LaunchResult l){t.terminalWarheadId=l.warheadId();t.terminalStartPosition=l.startPosition();t.terminalTargetPosition=l.intendedTarget();t.terminalLaunchGameTime=l.launchGameTime();t.terminalFlightTicks=l.flightTicks();t.terminalVisualSeed=l.visualSeed();t.terminalPlans.put(l.warheadId(),new RadarTerminalPlanSnapshot(l.warheadId(),l.clusterIndex(),l.clusterCount(),l.startPosition(),l.intendedTarget(),l.launchGameTime(),l.flightTicks(),l.visualSeed(),l.payloadType()));s.terminalToRoot.put(l.warheadId(),t.trackId);}private static void makeStrategicRoom(ServerLevel l,State s){while(strategicCount(s)>=MAX_STRATEGIC_TRACKS_PER_LEVEL){RadarTrack victim=s.tracks.values().stream().filter(t->t.kind!=RadarTrackKind.INTERCEPTOR).findFirst().orElse(null);if(victim==null)return;removeTrack(l,victim.trackId,RadarRemovalReason.EVICTED);}}private static long strategicCount(State s){return s.tracks.values().stream().filter(t->t.kind!=RadarTrackKind.INTERCEPTOR).count();}private static long interceptorCount(State s){return s.tracks.values().stream().filter(t->t.kind==RadarTrackKind.INTERCEPTOR).count();}private static void upsert(ServerLevel l,RadarTrack t){RadarSubscriptionManager.broadcast(l,new ClientboundRadarTrackUpsertPayload(l.getGameTime(),t.snapshot()));}private static String bounded(String s){return s==null||s.isBlank()?"SERVER":s.substring(0,Math.min(64,s.length()));}public record RadarTrackTelemetry(UUID trackId,RadarTrackKind kind,Optional<WarheadPayloadType> strategicPayloadType,Optional<AntiAirMissileVariant> interceptorVariant,RadarTrackPhase phase,Vec3 currentPosition,Vec3 currentVelocity,Vec3 predictedImpactPosition,long gameTime,RadarTrackSnapshot snapshot){}private static final class State{final LinkedHashMap<UUID,RadarTrack> tracks=new LinkedHashMap<>();final Map<UUID,UUID> terminalToRoot=new HashMap<>();final ArrayDeque<RadarImpactSnapshot> impacts=new ArrayDeque<>();}}
